import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"雜卦傳","description":"周易集註 - 雜卦傳","frontmatter":{"title":"雜卦傳","description":"周易集註 - 雜卦傳"},"headers":[],"relativePath":"classics/jizhu/073.md","filePath":"classics/jizhu/073.md"}'),r={name:"classics/jizhu/073.md"};function i(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="雜卦傳" tabindex="-1">雜卦傳 <a class="header-anchor" href="#雜卦傳" aria-label="Permalink to “雜卦傳”">​</a></h1><p>雜卦者，雜亂文王之序卦也。孔子將序卦一連者，特借其一端之理以序之，其寔恐後學顛倒文王所序之卦也。一端之理在所緩也，又恐後學以序卦為定理，不知其中有錯有綜，有此二體，故雜亂其卦。前者居於後，後者居於前，止將二體兩卦有錯有綜者下釋其意，故乾剛坤柔，比樂師憂是也。使非有此雜卦，象必失其傳矣。</p><p>乾剛坤柔。</p><p>此以錯言，言乾坤之情性也。文王序卦六十四卦止乾坤坎離大過頤小過中孚八卦相錯，蓋伏羲圓圖，乾坤坎離四正之卦本相錯，四隅之卦，兌錯艮，震錯巽，故大過，頤，小過，中孚所以相錯也。</p><p>比樂師憂。</p><p>此以綜言，因二卦同體，文王相綜為一卦，後言綜者仿此。順在內故樂，險在內故憂。凡綜卦有四正綜，四正者，比樂師憂，大有眾同人親之類也。四隅之卦，艮與震綜，皆一陽二陰之卦。艮可以言震，震可以言艮，兌與巽綜，皆二陽一陰之卦。兌可以言巽，巽可以言兌，如隨蠱鹹恆之類是也。有以正綜隅，隅綜正者，臨觀屯蒙之類是也。前儒不知乎此，所以言象失其傳，而不知象即藏於錯綜之中，因不細玩雜卦故也。</p><p>臨觀之義，或與或求。</p><p>此以綜言。君子之臨小人也，有發政施仁之意，故與;下民之觀君上也，有仰止觀光之心，故求。曰或者，二卦皆可言與求也。蓋求則必與，與則必求。</p><p>屯見而不失其居，蒙雜而著。</p><p>此以綜言。見者居九五之位也，居者以陽居陽也。八卦正位，坎在五，言九五雜於二陰之間，然居九五之位，剛健中正，故見而不失其居。蒙九二亦雜於二陰之間，然為發矇之主。故雜而著見，皆以坎之上下言，言蒙之坎上而為屯矣。見而不失其居，屯之坎下而為蒙矣，雜而又著。</p><p>震起也，艮止也。</p><p>此以綜言，震陽起於下，艮陽止於上。</p><p>損益盛衰之始也。</p><p>此以綜言，損上卦之艮，下而為益下卦之震。帝出乎震，故為盛之始。益上卦之巽，下而為損下卦之兌，說言乎兌，故為衰之始。震東兌西，春生秋殺，故為盛衰之始。</p><p>大畜時也，無妄災也。</p><p>此以綜言。大畜上卦之艮，下而為無妄下卦之震，故孔子曰剛自外來而為主於內。無妄下卦之震，上而為大畜之艮，故孔子曰剛上而尚賢。止其不能止者，非理之常，乃適然之時。得其不當得者，非理之常，乃偶然之禍。</p><p>萃聚而升不來也。</p><p>此以綜言。升上卦之三陰，下而為萃之下卦。三陰同聚，故曰萃。萃下卦之三陰，上而為升之上卦，三陰齊升，故曰升。惟升故不降下而來。</p><p>謙輕而豫怠也。</p><p>此以綜言。謙之上六，即豫之初六，故二爻皆言鳴。謙心虛，故自輕;豫志滿，故自怠。</p><p>噬嗑食也，賁無色也。</p><p>此以綜言。賁下卦之離，上而為噬嗑之上卦，故孔子曰柔得中而上行。噬嗑上卦之離，下而為賁之下卦，故孔子曰柔來而文剛。頤中有物，食其所有，白賁無色，文其所無。</p><p>兌見而巽伏也。</p><p>此以綜言，與震艮同，震艮以陽起止於上下，此則以陰見伏於上下。</p><p>隨無故也，蠱則飭也。</p><p>此以綜言，隨則以蠱上卦艮之剛，下而為震，故孔子曰剛來而下柔。蠱則以隨上卦兌之柔，下而為巽，故孔子曰剛上而柔下。隨無大故，故能相隨，蠱有大故，故當整飭。</p><p>剝爛也，復反也。</p><p>此以綜言，剝則生意漸盡而歸於無，復則生意復萌而反於有。</p><p>晉晝也，明夷誅也。</p><p>此以綜言。明夷下卦之離，進而為晉之上卦，故孔子曰柔進而上行，明在上而明著，明在下而明傷。</p><p>井通而困相遇也。</p><p>困上卦之兌，下而為井下卦之巽。井下卦之巽，上而為困上卦之兌。養而不窮，通也，即不困。剛過其揜，遇也，即不通。</p><p>鹹速也，恆久也。</p><p>此以綜言。故孔子曰柔上而剛下，剛上而柔下。有感則速，速則婚姻及時。有恆則久，久則夫婦偕老。</p><p>渙離也，節止也。</p><p>此以綜言。節上卦坎之剛來居渙之下卦，渙上卦巽之柔來居節之下卦。風散水故渙，渙則離而不止。澤防水故節，節則止而不離。</p><p>解緩也，蹇難也。</p><p>此以綜言。蹇下卦之艮往而為解上卦之震，出險之外，安舒寬緩之時，居險之下，大難切身之際。</p><p>睽外也，家人內也。</p><p>此以綜言。睽下卦之兌，即家人上卦之巽。睽於外而不相親，親於內而不相睽。</p><p>否泰反其類也。</p><p>此以綜言。大往小來，小往大來，故反其類。</p><p>大壯則止，遁則退也。止當作上</p><p>此以綜言，止字乃上字之誤。二卦相綜，遁之三爻即大壯之四爻，上字指大壯之四爻而言，退字指遁之三爻而言，皆相比於陰之爻也。孔子因周公三爻四爻之辭，故發此上退二字，言大壯則壯於大輿之輹，上往而進，遁則退而畜止臣妾，使制於陽，不使之浸而長也。故大壯則上，遁則退。</p><p>大有眾也，同人親也。</p><p>此以綜言。同人下卦之離進居大有之上卦，大有上卦之離來居同人之下卦，勢統於一，所愛者眾，情通於同，所與者親。</p><p>革去故也，鼎取新也。</p><p>此以綜言。鼎下卦之巽進而為革上卦之兌，水火相息，有去故之義。水火相烹，有從新之理。</p><p>小過過也，中孚信也。</p><p>此以錯言，過者逾其常，信者存其誠。</p><p>豐多故，親寡旅也。</p><p>此以綜言。旅下卦之艮，即豐上卦之震。人處豐盛，故多故舊。人在窮途，故寡親識。</p><p>離上而坎下也。</p><p>此以錯言，炎上潤下。</p><p>小畜寡也，履不處也。</p><p>此以綜言，二卦皆以柔為主。小畜柔得位但寡不能勝，眾陽所以不能畜，故曰寡也。履柔不得位，惟以悅體履虎尾，故曰不處也。不處者非所居也，故六三小象曰位不當。</p><p>需不進也，訟不親也。</p><p>此以綜言，天水相上下，安分待時，故不進。越理求勝，故不親。</p><p>大過顛也，頤養正也。（依蔡氏改正）</p><p>此以錯言。弱其本末故顛，擇其大小故正。《序卦》曰：頤者養也，不養則不可動，故受之以大過。有此作證，蔡氏方改正，所以《序卦》有功於易。</p><p>既濟定也，未濟男之窮也。（依蔡氏改正）</p><p>此以綜言，水火相為上下，六位皆當故定，三陽失位故窮。</p><p>歸妹女之終也，漸女歸待男行也。（依蔡氏改正）</p><p>此以綜言。歸妹下卦之兌，進而為漸上卦之巽，漸下卦之艮進而為歸妹上卦之震，歸妹者女事之終，待男者女嫁之禮。</p><p>姤遇也，柔遇剛也。夬決也，剛決柔也，君子道長，小人道消也。（依蔡氏改正）</p><p>此以綜言。君子小人，迭為盛衰，猶陰陽迭相消長。一柔在五陽之下，曰柔遇剛者，小人之遭遇，君子之所憂也。一柔在五陽之上，曰剛決柔者，君子之道長，小人之所憂也。易之為書，吉凶消長，進退存亡，不過此理此數而已，故以是終之。</p>',66)])])}const h=a(r,[["render",i]]);export{f as __pageData,h as default};
